#include <stdint.h>
#include <stddef.h>

#define VREF_3300MV 0
#define VREF_5000MV 1
#define VREF_2500MV 2

#define ADC_12BIT_LEVELS 4096u

static int vref_to_uv(int vref, uint32_t *uv)
{
    switch (vref) {
    case VREF_3300MV: *uv = 3300000u; return 0;
    case VREF_5000MV: *uv = 5000000u; return 0;
    case VREF_2500MV: *uv = 2500000u; return 0;
    default: return -1;
    }
}

int adc_window_to_uv(const uint16_t *samples, int count, int window,
                     int vref, uint32_t *out_uv)
{
    if (out_uv != NULL) {
        *out_uv = 0;
    }
    if (samples == NULL || out_uv == NULL || count <= 0 || window <= 0 || window > count) {
        return -1;
    }

    for (int i = 0; i < window; i++) {
        if ((int)samples[i] < 0 || (int)samples[i] > 4095) {
            return -2;
        }
    }

    uint32_t vref_uv = 0;
    if (vref_to_uv(vref, &vref_uv) != 0) {
        return -3;
    }

    uint32_t sum = 0;
    for (int i = 0; i < window; i++) {
        sum += (uint32_t)samples[i];
    }
    uint32_t avg = sum / (uint32_t)window;

    *out_uv = (uint32_t)(((uint64_t)avg * (uint64_t)vref_uv) / ADC_12BIT_LEVELS);
    return 0;
}
